;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;;                       ;;
;;   RLE Decompression   ;;  
;;                       ;;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; Decompress RLE chunk data into the chunk buffer
; RLE format: count, value pairs
rle_decompress_chunk:
    pusha
    mov si, chunk_rle_data
    mov di, chunk
    .loop:
        cmp si, chunk_rle_end
        jge .done
        lodsb               ; al = count
        mov cl, al
        xor ch, ch
        lodsb               ; al = value
        rep stosb            ; fill cx bytes with al
        jmp .loop
    .done:
    popa
    ret

; Generic RLE decompress: si = source RLE data, di = destination, bx = source end address
rle_decompress_generic:
    pusha
    .loop:
        cmp si, bx
        jge .done
        lodsb               ; al = count
        mov cl, al
        xor ch, ch
        lodsb               ; al = value
        rep stosb
        jmp .loop
    .done:
    popa
    ret

; Decompress all textures from RLE
rle_decompress_textures:
    pusha
    ; tx_character
    mov si, tx_character_rle
    mov di, tx_character
    mov bx, tx_character_rle_end
    call rle_decompress_generic
    ; tx_character_animation
    mov si, tx_character_animation_rle
    mov di, tx_character_animation
    mov bx, tx_character_animation_rle_end
    call rle_decompress_generic
    ; tx_brick
    mov si, tx_brick_rle
    mov di, tx_brick
    mov bx, tx_brick_rle_end
    call rle_decompress_generic
    ; tx_logo
    mov si, tx_logo_rle
    mov di, tx_logo
    mov bx, tx_logo_rle_end
    call rle_decompress_generic
    ; tx_rose
    mov si, tx_rose_rle
    mov di, tx_rose
    mov bx, tx_rose_rle_end
    call rle_decompress_generic
    popa
    ret

