; Toggle day/night mode
toggle_day_night:
    pusha
    cmp [sky_color], byte 0x35
    je .night
    mov [sky_color], byte 0x35
    jmp .redraw
    .night:
    mov [sky_color], byte 0x01
    .redraw:
    ; Redraw the background with new sky color
    mov bx, [sel_chunk_pixel]
    call camera
    popa
    ret

; Draw HUD showing selected block type at bottom of screen
draw_hud:
    pusha
    ; Draw block type indicators at bottom-right
    ; Position: row 190, starting at col 260
    mov bx, 320*190+260

    ; Draw 4 small block indicators (8x8 each)
    ; Block 3 = brick
    mov al, 0x2A
    call .draw_indicator
    ; Block 1 = grass
    mov al, 0x2E
    call .draw_indicator
    ; Block 7 = water
    mov al, 0x01
    call .draw_indicator
    ; Block 8 = sand
    mov al, 0x2C
    call .draw_indicator

    ; Draw selection marker under the selected block
    ; Calculate position based on sel_block_type
    mov bx, 320*199+260
    mov al, [sel_block_type]
    cmp al, 3
    je .sel0
    cmp al, 1
    je .sel1
    cmp al, 7
    je .sel2
    cmp al, 8
    je .sel3
    jmp .hud_done
    .sel0:
        jmp .draw_sel
    .sel1:
        add bx, 10
        jmp .draw_sel
    .sel2:
        add bx, 20
        jmp .draw_sel
    .sel3:
        add bx, 30
        jmp .draw_sel
    .draw_sel:
        mov cx, 8
        .sel_loop:
            mov [es:bx], byte 0x0F
            inc bx
            loop .sel_loop
    .hud_done:
    popa
    ret

    ; Draw a small 8x8 color indicator
    ; al = color, bx = screen position
    .draw_indicator:
        pusha
        mov cx, 8
        .ind_y:
            push cx
            mov cx, 8
            .ind_x:
                mov [es:bx], al
                inc bx
                loop .ind_x
            add bx, 320
            sub bx, 8
            pop cx
            loop .ind_y
        popa
        add bx, 10        ; space between indicators
        ret

